//! FORM autocomplete uses known-value reflection, independently of control hints.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form><input id=area name=q value=Seed><textarea id=text>Text</textarea><select id=select><option>A</option></select></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://form-name.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn form_name_canonical_exact_once_conversion_and_raw_units(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'name');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get name'||a.set.name!=='set name'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'name')||x.name!=='')throw 'canonical name';var calls=0;x.name={toString:function(){calls++;return '  FORM-É\ud800  ';},valueOf:function(){throw 'wrong hint';}};if(calls!==1||x.name!=='  FORM-É\ud800  '||x.getAttributeNS(null,'name')!==x.name)throw 'exact name';x.name=null;if(x.name!=='null')throw 'ordinary null';x.name=undefined;if(x.name!=='undefined')throw 'ordinary undefined';"#);}
#[test]
fn form_name_live_document_lookup_tracks_exact_current_names_without_changing_owners(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form'),editor=document.getElementById('area');x.name='checkout';if(document.checkout!==x||editor.form!==x||editor.value!=='Seed')throw 'live name';x.name='next';if(document.checkout!==undefined||document.next!==x||editor.form!==x)throw 'current name';x.removeAttribute('name');if(x.name!==''||document.next!==undefined)throw 'removed name';"#);}
#[test]
fn form_name_inert_exact_namespace_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml','form');x.setAttributeNS('urn:foreign','name','foreign');x.setAttributeNS(null,'NAME','uppercase');if(x.name!=='')throw 'namespace';x.name='A\ud800Z';var copy=x.cloneNode(false);copy.name='copy';if(x.name!=='A\ud800Z'||copy.name!=='copy'||copy.getAttributeNodeNS(null,'name')===x.getAttributeNodeNS(null,'name')||x.getAttributeNS('urn:foreign','name')!=='foreign')throw 'independent raw copy';"#);}

#[test]
fn form_name_named_control_precedence_preserves_saved_accessor_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),n=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'name');n.setAttribute('name','name');if(x.name!==n)throw 'named control precedence';var calls=0,watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});a.set.call(x,{toString:function(){calls++;return 'OFF';}});var records=watch.takeRecords();if(calls!==1||records.length!==1||records[0].attributeName!=='name'||x.name!==n||a.get.call(x)!=='OFF'||x.getAttributeNS(null,'name')!=='OFF')throw 'saved authority';a.set.call(x,'off\\ud800');if(a.get.call(x)!=='off\\ud800'||x.getAttributeNS(null,'name')!=='off\\ud800')throw 'named raw setter';a.set.call(x,'OFF');n.setAttribute('name','q');if(x.name!=='OFF')throw 'live named removal';");}
#[test]
fn form_name_resource_refusal_is_atomic_and_fresh_job_recovers(){for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form');x.name='off';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("form")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.form_name_get(object).map(|_|())}else{bridge.form_name_set(object,&Value::String("growing-unknown-name-value".into()))};assert!(result.is_err(),"getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.name='ON';if(x.name!=='ON'||document.getElementById('area').value!=='Seed')throw 'fresh recovery';");}}}
#[test]
fn form_name_attribute_writers_observe_raw_values_and_preserve_dirty_editor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),editor=document.getElementById('area');editor.value='Edited';x.name='on';var attribute=x.getAttributeNodeNS(null,'name'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['name']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('name','OFF');","x.setAttributeNS(null,'name','OFF');","attribute.value='OFF';","attribute.nodeValue='OFF';","attribute.textContent='OFF';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.name='on';watch.takeRecords();");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.name!=='OFF'||x.getAttributeNodeNS(null,'name')!==attribute||records.length!==1||records[0].oldValue!=='on'||records[0].attributeName!=='name'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('name');replacement.value='off\ud800';x.setAttributeNodeNS(replacement);if(x.name!=='off\ud800'||attribute.ownerElement!==null||replacement.ownerElement!==x||replacement.value!=='off\ud800')throw 'raw attribute replacement';"#);}

#[test]
fn form_name_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFormElement.prototype,'name'),calls=0;if(a.get.call(x)!=='')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-form-name.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'on';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://form-name.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin converted';a.set.call(x,'ON');if(x.name!=='ON')throw 'fresh recovery';");}

#[test]
fn form_name_brand_abrupt_conversion_and_prototype_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form'),P=HTMLFormElement.prototype,a=Object.getOwnPropertyDescriptor(P,'name'),calls=0;for(var bad of [{},document,document.body,Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';x.name={toString:function(){calls++;x.name='inner';return ' OUTER ';}};if(calls!==1||x.name!==' OUTER ')throw 'once';var marker={};try{x.name={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(x.name!==' OUTER '||x.getAttribute('data-side')!=='kept')throw 'abrupt';Object.defineProperty(P,'name',{get:function(){return 'author';},configurable:true});a.set.call(x,'native');if(x.name!=='author'||a.get.call(x)!=='native')throw 'saved authority';delete P.name;if(x.name!==undefined)throw 'deleted canonical';Object.defineProperty(P,'name',a);var C=HTMLFormElement;delete window.HTMLFormElement;if(!(x instanceof C)||a.get.call(x)!=='native')throw 'saved constructor';"#);}
